def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    fill = max(counts, key=counts.get)

    # Separator lines are the regularly spaced rows and columns that differ
    # substantially from the interior fill color.
    sr = [r for r in range(h)
          if sum(v != fill for v in grid[r]) > 0.6 * w]
    sc = [c for c in range(w)
          if sum(grid[r][c] != fill for r in range(h)) > 0.6 * h]

    def period(lines, limit):
        gaps = [b-a for a, b in zip(lines, lines[1:]) if b > a]
        if gaps:
            return min(gaps)
        # Fallback: infer the repeating period from row/column patterns.
        for p in range(1, limit):
            if all(grid[r][c] == grid[r+p][c]
                   for r in range(limit-p)
                   for c in range(w if limit == h else h)):
                return p
        return limit

    ph = period(sr, h)
    pw = period(sc, w)
    nr = max(1, (h - 1) // ph)
    nc = max(1, (w - 1) // pw)

    out = []
    for i in range(nr):
        row = []
        for j in range(nc):
            v = grid[i * ph][j * pw]
            row.append(fill if v == 5 else v)
        out.append(row)
    return out
